import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"七、逐字稿与模拟追问","description":"","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/07-逐字稿.md","filePath":"副业/保险展业/07-逐字稿.md","lastUpdated":1792941182000}'),d={name:"副业/保险展业/07-逐字稿.md"};function n(l,t,s,u,h,q){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="七、逐字稿与模拟追问" tabindex="-1">七、逐字稿与模拟追问 <a class="header-anchor" href="#七、逐字稿与模拟追问" aria-label="Permalink to &quot;七、逐字稿与模拟追问&quot;">​</a></h1><blockquote><p>本篇是 <a href="./06-三面准备">三面准备</a> 的<strong>练习版</strong>。 上一篇给的是框架和要点，这一篇是可以直接开口念的完整句子。</p></blockquote><hr><h2 id="_0-怎么用这篇" tabindex="-1">0. 怎么用这篇 <a class="header-anchor" href="#_0-怎么用这篇" aria-label="Permalink to &quot;0. 怎么用这篇&quot;">​</a></h2><ol><li><strong>先填空</strong>：把所有 <code>【】</code> 换成你的真实数字和事实</li><li><strong>再掐表练</strong>：Q1 必须卡在 1:50–2:10，其余题目不用计时</li><li><strong>最后练追问</strong>：第 9 章的压力追问才是真正的分水岭</li></ol><blockquote><p>⚠️ <code>【】</code> 没填完之前不要上场 —— 带着占位符说话会露怯。</p></blockquote><hr><h2 id="_1-q1-自我介绍-2-分钟逐字稿" tabindex="-1">1. Q1 自我介绍（2 分钟逐字稿） <a class="header-anchor" href="#_1-q1-自我介绍-2-分钟逐字稿" aria-label="Permalink to &quot;1. Q1 自我介绍（2 分钟逐字稿）&quot;">​</a></h2><h3 id="逐字稿" tabindex="-1">逐字稿 <a class="header-anchor" href="#逐字稿" aria-label="Permalink to &quot;逐字稿&quot;">​</a></h3><blockquote><p>&quot;面试官好，我是【名字】，【年龄】岁，【学历】，做前端开发已经 7 年。</p><p>这 7 年我感受很明显：<strong>前端在往下走</strong>，岗位在缩、要求越来越高；<strong>AI 在往上走</strong>，以前一个需求要五个人做，现在两个人加上 AI 就够了。与其继续在一条收缩的赛道上硬拼，不如去一条看得见在长的赛道上。</p><p>前几年我其实有点沉迷技术，觉得只要把技术学得够好，就能一直走下去。但这两年我也慢慢意识到，单靠一条技术线未必是全部。工资之外，我一直在想<strong>再拓展一份能长期做、还能慢慢积累的副业</strong>，而不是随便做点什么。</p><p>后来通过朋友介绍了解到友邦，也了解到<strong>保险这几年是在上行期的</strong>：老龄化在走，家庭保障意识在提高，头部公司还在扩。而代理人的时间是自己的、门槛靠积累，正好是我想要的那份副业。</p><p>这也是我来做保险的原因。&quot;</p></blockquote><h3 id="时长" tabindex="-1">时长 <a class="header-anchor" href="#时长" aria-label="Permalink to &quot;时长&quot;">​</a></h3><p>全文约 270 字，正常语速约 <strong>1 分 25 秒</strong>。 练的时候<strong>控制在 1 分 30 秒以内</strong>，剩下的余量留给主管追问。</p><h3 id="记忆锚点-记这-4-个词就够" tabindex="-1">记忆锚点（记这 4 个词就够） <a class="header-anchor" href="#记忆锚点-记这-4-个词就够" aria-label="Permalink to &quot;记忆锚点（记这 4 个词就够）&quot;">​</a></h3><blockquote><p><strong>下行 + AI 上行 → 副业诉求 → 保险上行期 → 这就是原因</strong></p></blockquote><h3 id="💡-这稿的三个设计" tabindex="-1">💡 这稿的三个设计 <a class="header-anchor" href="#💡-这稿的三个设计" aria-label="Permalink to &quot;💡 这稿的三个设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设计</th><th>为什么</th></tr></thead><tbody><tr><td>先讲行业周期，不先讲自己</td><td>主管先听判断力，再听你的经历</td></tr><tr><td>承认想搞副业，但说成&quot;能长期做、能积累&quot;</td><td>副业动机是加分项，说成随便做做直接踩投入度</td></tr><tr><td>结尾收在一句结论上</td><td>不要停在&quot;我还想再学学&quot;，要停在决定</td></tr></tbody></table><hr><h2 id="_2-q2-你和引荐人怎么认识的-逐字稿" tabindex="-1">2. Q2 你和引荐人怎么认识的？（逐字稿） <a class="header-anchor" href="#_2-q2-你和引荐人怎么认识的-逐字稿" aria-label="Permalink to &quot;2. Q2 你和引荐人怎么认识的？（逐字稿）&quot;">​</a></h2><h3 id="逐字稿-1" tabindex="-1">逐字稿 <a class="header-anchor" href="#逐字稿-1" aria-label="Permalink to &quot;逐字稿&quot;">​</a></h3><blockquote><p>&quot;我是通过【引荐人姓名】认识他/她的，到现在<strong>一年半</strong>。真正开始了解友邦也是这一年多里，前前后后参加了 <strong>3 场活动</strong>。</p><p>印象最深的是其中一场<strong>星享会</strong>，做介绍的是**【陈静总助】**。她是总助，位置不低，但我留意到一个细节——<strong>她已经 7 年没发过朋友圈了</strong>，说明靠朋友圈能触达的人其实很有限。可她还是在拓客，切口也很朴素：<strong>发自己孩子鸡娃的视频，从生活话题切进去</strong>，再自然地聊到家庭。</p><p>那场之后我意识到一件事：<strong>做这行不是拼谁人脉多，是拼谁敢不敢从最小的话题开始</strong>。而这件事我现在就可以开始练，不需要等什么大机会。&quot;</p></blockquote><h3 id="⚠️-关键-三个数字必须是真的" tabindex="-1">⚠️ 关键：三个数字必须是真的 <a class="header-anchor" href="#⚠️-关键-三个数字必须是真的" aria-label="Permalink to &quot;⚠️ 关键：三个数字必须是真的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>你的答案</th><th>注意</th></tr></thead><tbody><tr><td>认识引荐人</td><td><strong>一年半</strong></td><td>说具体，别说过多久</td></tr><tr><td>参加活动</td><td><strong>3 场</strong></td><td>说之前先数一遍，主管追问细节你得答得出</td></tr><tr><td>印象最深的一场</td><td><strong>星享会 · 陈静总助</strong></td><td>名字、时间、细节都要对得上</td></tr></tbody></table><h3 id="💡-拔高逻辑-这题的核心得分点" tabindex="-1">💡 拔高逻辑（这题的核心得分点） <a class="header-anchor" href="#💡-拔高逻辑-这题的核心得分点" aria-label="Permalink to &quot;💡 拔高逻辑（这题的核心得分点）&quot;">​</a></h3><p>主管不关心活动好不好玩，他关心<strong>你有没有在观察和思考</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平庸版：参加了星享会，氛围很好，讲解很专业 → 一般</span></span>
<span class="line"><span>拔高版：观察到&quot;总助 7 年不发朋友圈却还在拓客&quot;</span></span>
<span class="line"><span>        → 推出&quot;拓客拼切口不拼人脉基数&quot;</span></span>
<span class="line"><span>        → 落到我自己现在就能开始练 → 强</span></span></code></pre></div><blockquote><p>🎯 这个细节为什么好：一个位置不低的人也在从零拓客， 说明这行不是拼资源，是拼敢不敢开口 —— 而这恰恰是新人的第一关。</p></blockquote><hr><h2 id="_3-q3-介绍你了解的友邦-逐字稿" tabindex="-1">3. Q3 介绍你了解的友邦（逐字稿） <a class="header-anchor" href="#_3-q3-介绍你了解的友邦-逐字稿" aria-label="Permalink to &quot;3. Q3 介绍你了解的友邦（逐字稿）&quot;">​</a></h2><h3 id="🚨-上场前必须核对的事" tabindex="-1">🚨 上场前必须核对的事 <a class="header-anchor" href="#🚨-上场前必须核对的事" aria-label="Permalink to &quot;🚨 上场前必须核对的事&quot;">​</a></h3><p>前面这几个数字<strong>以官网或官方渠道为准</strong>，不要用二手文章的版本。</p><table tabindex="0"><thead><tr><th>#</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>1</td><td>1919 年于上海开启与中国的&quot;世纪之缘&quot;，后因战乱迁往境外</td><td>✅ 已确认</td></tr><tr><td>2</td><td>1992 年重回内地</td><td>✅ 已确认</td></tr><tr><td>3</td><td>2010 年在香港上市</td><td>✅ 已确认</td></tr><tr><td>4</td><td>2020 年获准将上海分公司改建为<strong>友邦人寿保险有限公司</strong>，成为内地首家外资独资人身保险公司</td><td>✅ 已确认</td></tr><tr><td>5</td><td>使命「以专业、诚信和爱，助力家庭和企业健康长久好生活」/ 愿景「中国最受信赖的保险公司」</td><td>✅ 已确认</td></tr><tr><td>6</td><td>中高端客群 + 高学历高素质代理人</td><td>✅ 已确认</td></tr><tr><td>7</td><td>代理人福利保障、&quot;双十&quot;比例、团队晋升基本法</td><td>☐ <strong>上场前问引荐人</strong></td></tr></tbody></table><h3 id="逐字稿-2" tabindex="-1">逐字稿 <a class="header-anchor" href="#逐字稿-2" aria-label="Permalink to &quot;逐字稿&quot;">​</a></h3><blockquote><p>&quot;我对友邦的了解是从一条时间线开始的。</p><p><strong>1919 年</strong>，友邦在上海开启了它和中国的&#39;世纪之缘&#39;；后来因为战乱迁到了境外；<strong>1992 年</strong>重回内地；<strong>2010 年</strong>在香港上市；<strong>2020 年</strong>，友邦获准把上海分公司改建为&#39;<strong>友邦人寿保险有限公司</strong>&#39;，成为中国内地<strong>首家外资独资的人身保险公司</strong>，统一经营内地的寿险业务。</p><p>它真正吸引我的，是三点。</p><p><strong>一，角色跟我是匹配的。</strong> 它服务的是中高端客户，代理人是高学历、高素质的人才——不是到处卖保单，是顾问式的活：先专业，后产品。我做了七年技术，一直是先把事情搞懂再动手。</p><p><strong>二，它的愿景是&#39;最受信赖&#39;。</strong> 信赖不是一次成交换来的，是很多年做下来才有的东西——这正是我想做的方向。</p><p><strong>三，它 100 多年没有离开中国。</strong> 从 1919 到 2020，中间经历了战乱、开放和市场几次大变化，这种投入不是做短期能解释的。</p><p>至于为什么选择友邦，我其实只看三条标准：<strong>扎根久、客群对、能续期</strong>。扎根久就是刚才那一百多年；客群对是中高端客户加高素质代理人；能续期，是代理人的收入里有续期，保障本身有周期——我愿意做的是跟着一个家庭很多年的事，不是一锤子买卖。&quot;</p></blockquote><h3 id="💡-杀手锏-把-吸引-和-选择-分开答" tabindex="-1">💡 杀手锏：把&quot;吸引&quot;和&quot;选择&quot;分开答 <a class="header-anchor" href="#💡-杀手锏-把-吸引-和-选择-分开答" aria-label="Permalink to &quot;💡 杀手锏：把&quot;吸引&quot;和&quot;选择&quot;分开答&quot;">​</a></h3><p>这题问的是<strong>两个不同的问题</strong>，混着答只能拿&quot;一般&quot;。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>哪些吸引你（我的感受） → 角色匹配 / 最受信赖 / 100 多年没离开 → 强</span></span>
<span class="line"><span>为什么选择友邦（我的标准）→ 扎根久 · 客群对 · 能续期（三词版） → 强</span></span></code></pre></div><blockquote><p>⚠️ <strong>最忌讳</strong>：把两条答案说成同一批优点。 没有标准的&quot;三条优点&quot;只是优点，<strong>先立标准、再用事实印证</strong>才是决策能力。</p></blockquote><h3 id="时间紧-只给-30-秒时" tabindex="-1">时间紧 / 只给 30 秒时 <a class="header-anchor" href="#时间紧-只给-30-秒时" aria-label="Permalink to &quot;时间紧 / 只给 30 秒时&quot;">​</a></h3><blockquote><p>&quot;我选友邦只看三条标准：<strong>扎根久</strong>——1919 年就在上海，2020 年拿下首家外资独资寿险资格；<strong>客群对</strong>——做中高端客户，代理人是高素质人才，跟我的背景匹配；<strong>能续期</strong>——收入里有续期，保障有周期。我不想只卖一份保单，我想做的是能跟着客户很多年的事。&quot;</p></blockquote><h3 id="❌-不要说" tabindex="-1">❌ 不要说 <a class="header-anchor" href="#❌-不要说" aria-label="Permalink to &quot;❌ 不要说&quot;">​</a></h3><ul><li>❌ &quot;友邦是世界五百强&quot;（任何人都能说，等于没准备）</li><li>❌ &quot;友邦的保险挺划算的&quot;（把保险公司说成便宜货，主管会反感）</li><li>❌ &quot;保险行业前景很好&quot;（没有一句是你自己的判断）</li><li>❌ 对牌照下自己没核实过的结论（比如&quot;这说明它要长期做&quot;）</li><li>❌ 把他家制度和别家搞混（追问一句就露）</li></ul><hr><h2 id="_4-q4-怎么看保险销售-优势-挑战-逐字稿" tabindex="-1">4. Q4 怎么看保险销售？优势？挑战？（逐字稿） <a class="header-anchor" href="#_4-q4-怎么看保险销售-优势-挑战-逐字稿" aria-label="Permalink to &quot;4. Q4 怎么看保险销售？优势？挑战？（逐字稿）&quot;">​</a></h2><h3 id="_4-1-观点段" tabindex="-1">4.1 观点段 <a class="header-anchor" href="#_4-1-观点段" aria-label="Permalink to &quot;4.1 观点段&quot;">​</a></h3><blockquote><p>&quot;我觉得保险销售的本质不是卖产品， 是帮一个家庭把它自己扛不住的那种最坏情况转移出去。</p><p>很多人买保险，不是因为觉得保险公司好， 是因为他清楚自己扛不住那个风险。</p><p>所以代理人真正的价值是 —— <strong>让客户在还没出事的时候，也愿意做这个决定。</strong> 难的是后半句。&quot;</p></blockquote><blockquote><p>💡 最后那句&quot;难的是后半句&quot;很关键： 它证明你知道这行难在哪，而不是站着说话。</p></blockquote><h3 id="_4-2-优势段-只说-3-个" tabindex="-1">4.2 优势段：只说 3 个 <a class="header-anchor" href="#_4-2-优势段-只说-3-个" aria-label="Permalink to &quot;4.2 优势段：只说 3 个&quot;">​</a></h3><p>主管记不住 5 个，只会觉得你背稿。挑 3 个，每个给证据。</p><table tabindex="0"><thead><tr><th>你的标签</th><th>证据（用你的真实经历替换）</th></tr></thead><tbody><tr><td><strong>自学能力（可教性）</strong></td><td>我这七年基本是靠自学往上走的，Vue 2 到 Vue 3、webpack 到 vite，都是自己啃文档啃下来的。保险的条款和责任免除是明文写着的，我一样能自己啃下来。</td></tr><tr><td><strong>讲清楚的能力</strong></td><td>我长期做技术讲解和方案评审，也一直在写博客，把复杂的东西讲成大白话是我的强项。而保险最难的恰恰是<strong>把复杂的条款讲成人话</strong>。</td></tr><tr><td><strong>抗压（被拒绝的承受力）</strong></td><td>我在一条收缩的赛道上待了七年，看得多的是业绩不达标和项目被砍。这套环境早就把&quot;扛得住&quot;这件事练出来了。</td></tr></tbody></table><blockquote><p>🎯 三个优势的顺序别换：<strong>先给能证明的（自学、讲清楚），最后给性格类的（抗压）</strong>。 主管问优势时，前两个证明&quot;可教性 + 表达能力&quot;，第三个补&quot;交际与抗压&quot;。</p></blockquote><h3 id="_4-3-挑战段-本题得分点" tabindex="-1">4.3 挑战段：<strong>本题得分点</strong> <a class="header-anchor" href="#_4-3-挑战段-本题得分点" aria-label="Permalink to &quot;4.3 挑战段：**本题得分点**&quot;">​</a></h3><p>说&quot;我没挑战&quot;直接判差。用三段式：<strong>认一个 → 说难在哪 → 说怎么应对</strong>。</p><blockquote><p>&quot;我预判最大的挑战是<strong>前期从零开始拓客</strong>。</p><p>我之前做技术是站在系统训练之上的 —— 有文档、有教程、有标准答案。 但拓客没有标准答案，而且大部分时候， 你连一个明确的拒绝都拿不到，对方只会说&quot;暂时不需要&quot;。</p><p>我对这个有两个准备：</p><p>一是<strong>降低对拒绝的敏感度</strong>。 我准备把前三个月的每一次拒绝都当成数据记下来，做复盘， 而不是当成对我个人的否定。</p><p>二是<strong>先跑量再跑质</strong>。 我给自己定了【X】次面谈的月度目标，用面谈量把成交率这个变量稀释掉 —— 我不能保证每一单都成，但我能保证谈的人够多。&quot;</p></blockquote><h3 id="可替换的挑战-选一个你真认同的" tabindex="-1">可替换的挑战（选一个你真认同的） <a class="header-anchor" href="#可替换的挑战-选一个你真认同的" aria-label="Permalink to &quot;可替换的挑战（选一个你真认同的）&quot;">​</a></h3><ul><li><strong>收入前期波动</strong>：从确定工资到佣金制，需要缓冲</li><li><strong>开口求助的心理关</strong>：主动麻烦别人是最难的一步</li><li><strong>从熟人到陌生</strong>：熟人市场有限，长期要建陌生信任</li><li><strong>知识门槛</strong>：保险、法律、税务、医学都得懂一点</li></ul><h3 id="❌-不要说-1" tabindex="-1">❌ 不要说 <a class="header-anchor" href="#❌-不要说-1" aria-label="Permalink to &quot;❌ 不要说&quot;">​</a></h3><ul><li>❌ &quot;我觉得我没什么挑战&quot;（= 差）</li><li>❌ &quot;我最大的挑战是我还没钱&quot;（暴露动机）</li><li>❌ 说挑战但不说怎么应对（说完必须接&quot;我打算……&quot;）</li></ul><hr><h2 id="_5-q5-三个月收入目标-逐字稿-·-最高权重" tabindex="-1">5. Q5 三个月收入目标（逐字稿 · 最高权重） <a class="header-anchor" href="#_5-q5-三个月收入目标-逐字稿-·-最高权重" aria-label="Permalink to &quot;5. Q5 三个月收入目标（逐字稿 · 最高权重）&quot;">​</a></h2><blockquote><p>🎯 主管在这里做最后判断：<strong>你是来玩票的，还是来换赛道的。</strong></p></blockquote><h3 id="_5-1-先算-别猜" tabindex="-1">5.1 先算，别猜 <a class="header-anchor" href="#_5-1-先算-别猜" aria-label="Permalink to &quot;5.1 先算，别猜&quot;">​</a></h3><p>不要凭空想一个数字，用这个公式倒推：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三个月签单数 ≈ 月均面谈次数 × 面谈成交率</span></span>
<span class="line"><span></span></span>
<span class="line"><span>举例：每月 20 次面谈 × 成交率 15% ≈ 3 单/月</span></span></code></pre></div><blockquote><p>你心里大概有个数：朋友圈有多少人可约、每月能跑几场活动。 <strong>用它算出来的数字才站得住</strong>，主管追问&quot;凭什么&quot;你答得出来。</p></blockquote><blockquote><p>⚠️ <strong>上场前必填</strong>：你的 A/B/C 名单实际有多少人、你朋友圈能约到的有多少、 每月实际能跑几场活动。<strong>主管追问&quot;这个数字怎么来的&quot;，你要能当场算给他看。</strong> 编一个够大又解释不了的数字，比报一个保守但算得清的数字危险得多。</p></blockquote><h3 id="_5-2-目标-三档报" tabindex="-1">5.2 目标：三档报 <a class="header-anchor" href="#_5-2-目标-三档报" aria-label="Permalink to &quot;5.2 目标：三档报&quot;">​</a></h3><p>只报一个数，要么显得飘，要么显得不认真。</p><table tabindex="0"><thead><tr><th>档</th><th>单数</th><th>保费</th><th>说明</th></tr></thead><tbody><tr><td><strong>保底</strong></td><td>【X】单</td><td>【X】万</td><td>最坏情况我也接受，因为前期重心是打底</td></tr><tr><td><strong>目标</strong></td><td>【X】单</td><td>【X】万</td><td>我真正奔着的</td></tr><tr><td><strong>冲刺</strong></td><td>【X】单</td><td>【X】万</td><td>状态好能摸到</td></tr></tbody></table><h3 id="_5-3-逐月拆解-主管最爱听" tabindex="-1">5.3 逐月拆解（主管最爱听） <a class="header-anchor" href="#_5-3-逐月拆解-主管最爱听" aria-label="Permalink to &quot;5.3 逐月拆解（主管最爱听）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>关键动作</th></tr></thead><tbody><tr><td><strong>第 1 月</strong></td><td>保底级 · 打底</td><td>系统学完产品条款；盘点【X】个缘故市场的人分 A/B/C；跟引荐人跑【X】场活动；每周新增【X】好友</td></tr><tr><td><strong>第 2 月</strong></td><td>目标级 · 建面谈量</td><td>独立参加【X】场活动；完成【X】次面谈；把每个客户的家庭情况建档</td></tr><tr><td><strong>第 3 月</strong></td><td>冲刺级 · 转化</td><td>集中促成和追单；启动转介绍；做第一次完整复盘</td></tr></tbody></table><h3 id="_5-4-准备好了吗-要答三层" tabindex="-1">5.4 &quot;准备好了吗&quot;要答三层 <a class="header-anchor" href="#_5-4-准备好了吗-要答三层" aria-label="Permalink to &quot;5.4 &quot;准备好了吗&quot;要答三层&quot;">​</a></h3><blockquote><p>&quot;准备分三块：</p><p><strong>知识上</strong> —— 我已经能讲清楚重疾和医疗的区别、责任免除和现金价值是什么， 能用大白话讲，不靠术语。</p><p><strong>名单上</strong> —— 我已经列了【X】个人，分了三类： A 类是有需求有信任的，这周就约；B 类是关系一般需要维护的； C 类是只保持联系的。</p><p><strong>节奏上</strong> —— 我下周【具体动作：约引荐人一起复盘 / 自己跑一场活动 / 约第一个客户喝咖啡】， 不是等入职了才开始。&quot;</p></blockquote><h3 id="_5-5-💡-杀手锏-第一周做什么" tabindex="-1">5.5 💡 杀手锏：第一周做什么 <a class="header-anchor" href="#_5-5-💡-杀手锏-第一周做什么" aria-label="Permalink to &quot;5.5 💡 杀手锏：第一周做什么&quot;">​</a></h3><blockquote><p>&quot;如果我通过了，第一周我会这么排： <strong>第 1 天</strong> 跟您过一遍我那份 A/B/C 名单； <strong>第 2 到 3 天</strong> 把优先级最高的那【X】个人电话过一遍； <strong>第 4 到 5 天</strong> 约出第一个面谈； <strong>周末</strong> 跟引荐人跑一场活动。</p><p>一周之内我要有第一次真实的客户面谈。&quot;</p></blockquote><blockquote><p>🎯 主管最怕新人&quot;等安排&quot;。你说&quot;一周之内有第一次面谈&quot;， 等于告诉他<strong>你不用催我</strong>。</p></blockquote><h3 id="❌-不要说-2" tabindex="-1">❌ 不要说 <a class="header-anchor" href="#❌-不要说-2" aria-label="Permalink to &quot;❌ 不要说&quot;">​</a></h3><ul><li>❌ &quot;三个月先保证温饱就行&quot;（目标感 = 差）</li><li>❌ &quot;我没有具体目标，需要公司给我定&quot;（直接踩投入度）</li><li>❌ 只说目标不说拆解，或只说拆解不说准备</li></ul><hr><h2 id="_6-q6-工作模式-怎么拓客-逐字稿" tabindex="-1">6. Q6 工作模式？怎么拓客？（逐字稿） <a class="header-anchor" href="#_6-q6-工作模式-怎么拓客-逐字稿" aria-label="Permalink to &quot;6. Q6 工作模式？怎么拓客？（逐字稿）&quot;">​</a></h2><h3 id="_6-1-工作模式-说主管的内部语言" tabindex="-1">6.1 工作模式（说主管的内部语言） <a class="header-anchor" href="#_6-1-工作模式-说主管的内部语言" aria-label="Permalink to &quot;6.1 工作模式（说主管的内部语言）&quot;">​</a></h3><blockquote><p>&quot;我理解这份工作的常态是被拒绝，产出靠的是稳定的动作量，不是灵感。</p><p>所以时间上是自主管理，早上安排当天行程，晚间是活动和社交时段。 主线是活动加转介绍双轮 —— 活动负责拿到新面孔，转介绍负责拿到高意向的。 每场活动结束之后，48 小时之内我会把在场的人全部跟进一遍。</p><p>我把它变成日程表，靠系统出单，而不是靠某一单碰运气。&quot;</p></blockquote><h3 id="_6-2-拓客四条渠道-数量" tabindex="-1">6.2 拓客四条渠道 + 数量 <a class="header-anchor" href="#_6-2-拓客四条渠道-数量" aria-label="Permalink to &quot;6.2 拓客四条渠道 + 数量&quot;">​</a></h3><blockquote><p>&quot;我打算分四条渠道走。</p><p><strong>第一，缘故市场。</strong> 我盘了【X】个熟人，按 A/B/C 分层，A 类这周就约。</p><p><strong>第二，活动获客。</strong> 每月参加【X】场，每场之后 48 小时内全量跟进。</p><p><strong>第三，线上内容。</strong> 每周发【X】条，不刷屏、不群发，讲的是具体的案例和条款细节。</p><p><strong>第四，转介绍。</strong> 每成交一个、或者每服务完一个客户，我都会自然地提一次， 而且会明确告诉对方：只是免费帮朋友做个分析，不买没关系。降低对方的压力。&quot;</p></blockquote><h3 id="_6-3-动作指标" tabindex="-1">6.3 动作指标 <a class="header-anchor" href="#_6-3-动作指标" aria-label="Permalink to &quot;6.3 动作指标&quot;">​</a></h3><blockquote><p>&quot;我的第一个月这样定： 每周新增好友【X】个， 每月参加活动【X】场， 每月完成面谈【X】次， 每周日晚上做一次复盘 —— 这周见了谁、卡在哪、下周做什么。&quot;</p></blockquote><h3 id="❌-不要说-3" tabindex="-1">❌ 不要说 <a class="header-anchor" href="#❌-不要说-3" aria-label="Permalink to &quot;❌ 不要说&quot;">​</a></h3><ul><li>❌ &quot;我先在公司学一学再说&quot;（= 差，主管最怕这个）</li><li>❌ &quot;主要靠熟人&quot;（主管会追问：那熟人用完了怎么办）</li><li>❌ &quot;我会多发朋友圈&quot;（太低阶，要说内容和频次）</li></ul><hr><h2 id="_7-q7-家人支持吗-逐字稿-·-最容易翻车" tabindex="-1">7. Q7 家人支持吗？（逐字稿 · 最容易翻车） <a class="header-anchor" href="#_7-q7-家人支持吗-逐字稿-·-最容易翻车" aria-label="Permalink to &quot;7. Q7 家人支持吗？（逐字稿 · 最容易翻车）&quot;">​</a></h2><h3 id="🚨-上场前必须和家里人对齐-4-件事" tabindex="-1">🚨 上场前必须和家里人对齐 4 件事 <a class="header-anchor" href="#🚨-上场前必须和家里人对齐-4-件事" aria-label="Permalink to &quot;🚨 上场前必须和家里人对齐 4 件事&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>对齐什么</th><th>为什么重要</th></tr></thead><tbody><tr><td>1</td><td>收入预期：前 3-6 个月可能不稳定</td><td>最容易吵架的点</td></tr><tr><td>2</td><td>社保：自己交还是挂靠，别断缴</td><td>现实问题，想细了是加分</td></tr><tr><td>3</td><td>时间：活动常在晚上和周末</td><td>要落到具体分工</td></tr><tr><td>4</td><td>孩子：谁接送、谁做饭、谁辅导作业</td><td>主管问的就是这个</td></tr></tbody></table><h3 id="逐字稿-3" tabindex="-1">逐字稿 <a class="header-anchor" href="#逐字稿-3" aria-label="Permalink to &quot;逐字稿&quot;">​</a></h3><blockquote><p>&quot;家里<strong>支持</strong>。</p><p>具体已经安排好了：</p><ul><li>【孩子 / 家人】这块由【谁】负责，接送和作业都已经定下来了；</li><li>社保我确认过，会【自己交 / 转灵活就业】，不断缴；</li><li>时间上我清楚这行的作息是早起加晚间和周末活动，家里也知道这个节奏；</li><li>三个月收入目标我和家里沟通过，他们知道前期会有一个爬坡期。</li></ul><p>我这边没有牵绊，可以全投入。&quot;</p></blockquote><h3 id="💡-为什么这样说有效" tabindex="-1">💡 为什么这样说有效 <a class="header-anchor" href="#💡-为什么这样说有效" aria-label="Permalink to &quot;💡 为什么这样说有效&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你说的</th><th>主管听到的</th></tr></thead><tbody><tr><td>&quot;家里支持&quot;（不犹豫）</td><td>这个人想清楚了，不是头脑发热</td></tr><tr><td>&quot;社保不断缴&quot;</td><td>有责任感，不是只想赚快钱</td></tr><tr><td>&quot;目标沟通过&quot;</td><td>把这件事当正式决定在做</td></tr><tr><td>&quot;没有牵绊&quot;</td><td>我不用担心他中途走</td></tr></tbody></table><h3 id="⚠️-万一确实有困难" tabindex="-1">⚠️ 万一确实有困难 <a class="header-anchor" href="#⚠️-万一确实有困难" aria-label="Permalink to &quot;⚠️ 万一确实有困难&quot;">​</a></h3><p>坦诚 + 有解法 + 明确边界：</p><blockquote><p>&quot;孩子白天由【谁】带，晚上和周末我能保证。 这块是我唯一需要协调的，我已经安排好了，不会影响展业时间。&quot;</p></blockquote><p><strong>有困难但有解法 = 可信；只抛困难不给解法 = 差。</strong></p><h3 id="❌-不要说-4" tabindex="-1">❌ 不要说 <a class="header-anchor" href="#❌-不要说-4" aria-label="Permalink to &quot;❌ 不要说&quot;">​</a></h3><ul><li>❌ &quot;家里还不知道&quot;（直接暴露你没准备）</li><li>❌ &quot;先干着看，家里有意见再说&quot;</li><li>❌ 犹豫、含糊、&quot;这个……其实还好&quot;（一听就是有问题）</li><li>❌ 主动放大困难（&quot;没人带孩子可能顾不上&quot;——就算真这样，也要带上解法）</li></ul><hr><h2 id="_8-三个必须改掉的说话习惯" tabindex="-1">8. 三个必须改掉的说话习惯 <a class="header-anchor" href="#_8-三个必须改掉的说话习惯" aria-label="Permalink to &quot;8. 三个必须改掉的说话习惯&quot;">​</a></h2><table tabindex="0"><thead><tr><th>习惯</th><th>改成</th></tr></thead><tbody><tr><td>&quot;还在了解阶段&quot;&quot;熟悉熟悉就好&quot;</td><td>给具体数字和具体日期</td></tr><tr><td>&quot;我觉得这个应该可以&quot;</td><td>&quot;我打算这么做，具体是……&quot;</td></tr><tr><td>&quot;先干着看&quot;</td><td>&quot;我的目标是……，达成的话……&quot;</td></tr></tbody></table><blockquote><p>🎯 <strong>含糊 = 差</strong>。这是评分表里最容易被忽略的规则。</p></blockquote><hr><h2 id="_9-模拟压力追问-真正的分水印" tabindex="-1">9. 模拟压力追问（真正的分水印） <a class="header-anchor" href="#_9-模拟压力追问-真正的分水印" aria-label="Permalink to &quot;9. 模拟压力追问（真正的分水印）&quot;">​</a></h2><p>主管大概率会追问这些。<strong>这 7 题答不好，前面全白答。</strong> 其中 <strong>Q8-0（副业 vs 干不下去）是必考题</strong> —— 你在 Q1 里主动提了&quot;副业&quot;，主管一定会追。</p><h3 id="q8-0-⚠️-最危险的一问-「你说想做副业-——-那你是想好了-还是技术干不下去了-」" tabindex="-1">Q8-0 ⚠️ 最危险的一问：「你说想做副业 —— 那你是想好了，还是技术干不下去了？」 <a class="header-anchor" href="#q8-0-⚠️-最危险的一问-「你说想做副业-——-那你是想好了-还是技术干不下去了-」" aria-label="Permalink to &quot;Q8-0 ⚠️ 最危险的一问：「你说想做副业 —— 那你是想好了，还是技术干不下去了？」&quot;">​</a></h3><blockquote><p>主管一定会问这题，因为你在 Q1 里主动提了&quot;副业&quot;。 <strong>答砸了，前面所有题都白答。</strong></p></blockquote><blockquote><p>&quot;我想先说清楚：我想做保险，是我自己判断出来的结果，不是因为我在现在的岗位上待不下去。</p><p>这两年行业确实在下行，但我在做的是往一条在长的赛道上走，不是在逃离哪条赛道。 如果只是干不下去才来，那我不会花一年半去了解、也不会去参加活动。</p><p>至于形态，我想的是<strong>先以副业的方式切进来，把方法跑通</strong>—— 因为我不想在还没搞懂这件事的时候就做全职的决定。 但我要说清楚：我不是来玩票的，这三件事我都能保证 —— <strong>一、社保不断缴</strong>；<strong>二、收入预期我提前和家里对齐过</strong>； <strong>三、一旦跑通，我会把它当长期的事做下去</strong>，而不是刚好做够三个月就算了。</p><p>如果最后全职做，那是我验证完之后的升级，不是我一开始的退路。&quot;</p></blockquote><blockquote><p>🎯 这题的核心不是&quot;解释副业&quot;，是<strong>把&quot;副业&quot;翻译成&quot;我有判断、有节奏、有退路&quot;</strong>。 三句护身符：<strong>不是待不下去 · 先验证再决定 · 跑通就长期做</strong>。</p></blockquote><hr><h3 id="q8「你技术做了-7-年-凭什么觉得能做好保险-」" tabindex="-1">Q8「你技术做了 7 年，凭什么觉得能做好保险？」 <a class="header-anchor" href="#q8「你技术做了-7-年-凭什么觉得能做好保险-」" aria-label="Permalink to &quot;Q8「你技术做了 7 年，凭什么觉得能做好保险？」&quot;">​</a></h3><blockquote><p>&quot;我不觉得这是两个行当。</p><p>我做技术的核心能力是快速搞懂一个陌生系统， 然后找到规律把它讲给别人听。保险的条款、产品、责任， 本质上也是一个复杂的系统。</p><p>而且有一点是我的优势 —— 保险是个信任生意，客户凭什么信我？ 他不会看我的职级，他只会看我这个人讲的东西有没有道理、 有没有认真帮他看问题。这个恰恰是我一直擅长的事。&quot;</p></blockquote><h3 id="q9「你说三个月能签【x】单-签不到怎么办-」" tabindex="-1">Q9「你说三个月能签【X】单，签不到怎么办？」 <a class="header-anchor" href="#q9「你说三个月能签【x】单-签不到怎么办-」" aria-label="Permalink to &quot;Q9「你说三个月能签【X】单，签不到怎么办？」&quot;">​</a></h3><blockquote><p>&quot;如果签不到，我会先看是哪一环断了。</p><p>是面谈量不够，还是约到了但没需求， 还是需求对了但方案没打动他 —— 这三个原因对应的动作完全不一样。</p><p>面谈量不够就加活动；约不到人就是我的邀约话术要改； 方案不打动人就回到需求挖掘，看是不是我讲错了重点。</p><p>我会做月度复盘，把原因拆开看，而不是简单地觉得&#39;这行真难&#39;。&quot;</p></blockquote><h3 id="q10「保险行业留存率很低-很多人干半年就走了-你凭什么不一样-」" tabindex="-1">Q10「保险行业留存率很低，很多人干半年就走了，你凭什么不一样？」 <a class="header-anchor" href="#q10「保险行业留存率很低-很多人干半年就走了-你凭什么不一样-」" aria-label="Permalink to &quot;Q10「保险行业留存率很低，很多人干半年就走了，你凭什么不一样？」&quot;">​</a></h3><blockquote><p>&quot;我不否认这个行业流动性高。</p><p>走的人大概是因为两种原因：一种是业绩长期上不去，收入撑不住； 另一种是没有意义感，不知道自己在积累什么。</p><p>我给自己设了三个月的动作量指标， 目标不是靠情绪撑着，而是靠日程表撑着 —— 每天该加几个好友、该约几个人，是可以量化的，不靠当天状态好不好。</p><p>而且我选了健康和长期储蓄这条线，本身就是可以持续做一辈子的生意， 不是一锤子买卖。&quot;</p></blockquote><h3 id="q11「家里真的支持吗-你家里人怎么看-」" tabindex="-1">Q11「家里真的支持吗？你家里人怎么看？」 <a class="header-anchor" href="#q11「家里真的支持吗-你家里人怎么看-」" aria-label="Permalink to &quot;Q11「家里真的支持吗？你家里人怎么看？」&quot;">​</a></h3><blockquote><p>（<strong>不要犹豫，直接重复第 7 题的核心信息</strong>）</p><p>&quot;支持。家里知道我做的是长期的事业， 收入前期的爬坡期我们提前谈过。 孩子和社保这些具体安排我都落到位了，不会成为中途停下来的理由。&quot;</p></blockquote><h3 id="q12「你觉得引荐人怎么评价你-」" tabindex="-1">Q12「你觉得引荐人怎么评价你？」 <a class="header-anchor" href="#q12「你觉得引荐人怎么评价你-」" aria-label="Permalink to &quot;Q12「你觉得引荐人怎么评价你？」&quot;">​</a></h3><blockquote><p>&quot;我觉得他会说我愿意学、肯下功夫。</p><p>我承认我起步比有些新人慢一点 —— 我不是那种开口就自来熟的人， 但我做事比较扎实，学过的东西是真的学进去了。</p><p>我相信在这个行业里，前期扎实一点，后面会跑得更稳。&quot;</p></blockquote><h3 id="q13「你还有什么想问的-」" tabindex="-1">Q13「你还有什么想问的？」 <a class="header-anchor" href="#q13「你还有什么想问的-」" aria-label="Permalink to &quot;Q13「你还有什么想问的？」&quot;">​</a></h3><p><strong>✅ 值得问的：</strong></p><ol><li>&quot;您团队现在多少人？今年新人的留存情况怎么样？&quot; → 问留存 = 你想长期干</li><li>&quot;您觉得一个新人前三个月最关键的动作是什么？&quot; → <strong>顺便拿到主管对你的期望值</strong></li><li>&quot;团队里在家庭保障方向做得好的人是谁？我想去请教一下。&quot; → 谦逊 + 想融入</li><li>&quot;公司对新人的培训体系是怎样的？&quot; → 关心成长路径</li></ol><p><strong>❌ 不要问：</strong></p><ul><li>❌ 底薪、佣金（三面谈钱 = 减分，留到终面）</li><li>❌ &quot;我能只做兼职吗&quot;（直接踩投入度）</li><li>❌ &quot;多久能出单&quot;（把代理当投资，问法就错了）</li></ul><hr><h2 id="_10-临场一页速记" tabindex="-1">10. 临场一页速记 <a class="header-anchor" href="#_10-临场一页速记" aria-label="Permalink to &quot;10. 临场一页速记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>一句话核心</th></tr></thead><tbody><tr><td><strong>Q8-0 副业追问</strong></td><td><strong>不是待不下去 · 先验证再决定 · 跑通就长期做</strong></td></tr><tr><td>Q1 自我介绍</td><td>下行 + AI 上行 → 副业诉求 → 保险上行期 → 这就是原因</td></tr><tr><td>Q2 引荐人</td><td><strong>一年半 / 3 场 / 星享会</strong> + &quot;7 年不发朋友圈也在拓客&quot;</td></tr><tr><td>Q3 友邦了解</td><td>时间线四个年份 → 三点吸引力 → <strong>扎根久·客群对·能续期</strong></td></tr><tr><td>Q4 销售观/挑战</td><td>观点清晰 + 3 个优势 + 1 个真挑战带解法</td></tr><tr><td>Q5 三个月目标</td><td>三档 + 逐月拆解 + <strong>我第一周就有第一次面谈</strong></td></tr><tr><td>Q6 拓客</td><td>双轮 + 四渠道 + 数量 + 第一周动作清单</td></tr><tr><td>Q7 家庭</td><td>先说支持 + 社保不断缴 + 目标已沟通</td></tr></tbody></table><blockquote><p><strong>三个致命词，烂熟于心：</strong><strong>数字</strong>（量化一切）· <strong>动作</strong>（落到可验证的下一步）· <strong>安排</strong>（家庭已谈妥）</p></blockquote><hr><h2 id="🔗-相关文章" tabindex="-1">🔗 相关文章 <a class="header-anchor" href="#🔗-相关文章" aria-label="Permalink to &quot;🔗 相关文章&quot;">​</a></h2><ul><li><a href="./06-三面准备">六、三面准备</a> —— 评分表拆解（框架篇，练习前先看）</li><li><a href="./05-获客转介绍">五、获客与转介绍</a> —— 拓客细节</li><li><a href="./04-促成成交">四、促成成交</a> —— 促成与转介绍话术</li></ul><blockquote><p>💡 填完 <code>【】</code> 之后，建议找个人对着录音念一遍 Q1， 回放听有没有超过 2 分钟、有没有出现&quot;这个&quot;&quot;大概&quot;&quot;应该&quot;这些含糊词。</p></blockquote>`,136)])])}const b=o(d,[["render",n]]);export{p as __pageData,b as default};
